import pickle
import base64
import hmac
import hashlib
import os
from flask import Flask, request, jsonify, abort
from functools import wraps

app = Flask(__name__)

# Session signing key - loaded from environment
SESSION_SECRET = os.environ.get('SESSION_SECRET', 'dev-secret-key-change-me')

def verify_signature(data, signature):
    """Verify HMAC signature of session data."""
    expected = hmac.new(SESSION_SECRET.encode(), data.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def require_internal_header(f):
    """Check for internal service mesh header."""
    @wraps(f)
    def decorated(*args, **kwargs):
        # X-Internal-Service header is set by the service mesh sidecar
        if not request.headers.get('X-Internal-Service'):
            abort(403, description="Missing internal service header")
        return f(*args, **kwargs)
    return decorated

class SessionStore:
    """Server-side session store using pickle serialization."""

    def __init__(self):
        self._sessions = {}

    def save_session(self, session_id, data):
        """Serialize and store session data."""
        serialized = base64.b64encode(pickle.dumps(data)).decode('utf-8')
        self._sessions[session_id] = serialized
        return serialized

    def load_session(self, session_blob):
        """Deserialize session data from client-provided blob."""
        try:
            raw = base64.b64decode(session_blob)
            return pickle.loads(raw)
        except Exception as e:
            app.logger.warning(f"Failed to deserialize session: {e}")
            return None

    def restore_from_backup(self, backup_payload):
        """Restore sessions from a backup payload (admin operation)."""
        raw = base64.b64decode(backup_payload)
        restored = pickle.loads(raw)
        self._sessions.update(restored)
        return len(restored)

store = SessionStore()

@app.route('/api/session', methods=['POST'])
def create_session():
    """Create a new session with user preferences."""
    data = request.get_json()
    if not data or 'user_id' not in data:
        abort(400)
    session_id = os.urandom(16).hex()
    blob = store.save_session(session_id, data)
    return jsonify({'session_id': session_id, 'token': blob})

@app.route('/api/session/restore', methods=['POST'])
def restore_session():
    """Restore a session from a client-provided token.

    The token is a base64-encoded serialized session object that
    was previously issued by create_session.
    """
    data = request.get_json()
    if not data or 'token' not in data:
        abort(400)

    token = data['token']
    # Signature verification for tamper detection
    signature = data.get('sig', '')
    if signature and not verify_signature(token, signature):
        abort(403, description="Invalid signature")

    # Deserialize the session token
    session_data = store.load_session(token)
    if session_data is None:
        abort(400, description="Invalid session token")

    return jsonify({'status': 'restored', 'data': session_data})

@app.route('/api/admin/restore-backup', methods=['POST'])
@require_internal_header
def admin_restore_backup():
    """Admin endpoint to restore session store from backup."""
    data = request.get_json()
    if not data or 'backup' not in data:
        abort(400)
    count = store.restore_from_backup(data['backup'])
    return jsonify({'status': 'ok', 'restored_count': count})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
